CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE applicants (id UUID PRIMARY KEY, user_id UUID UNIQUE NOT NULL REFERENCES users(id), business_name VARCHAR(255) NOT NULL, pan VARCHAR(10) NOT NULL, gstin VARCHAR(15) NOT NULL, address TEXT NOT NULL, blacklisted BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE loan_applications (id UUID PRIMARY KEY, applicant_id UUID NOT NULL REFERENCES applicants(id), amount_requested NUMERIC(18,2) NOT NULL, purpose TEXT NOT NULL, status VARCHAR(40) NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), decision_reason TEXT);
CREATE TABLE compliance_checks (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES loan_applications(id), check_type VARCHAR(40) NOT NULL, passed BOOLEAN NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE risk_assessments (id UUID PRIMARY KEY, application_id UUID UNIQUE NOT NULL REFERENCES loan_applications(id), probability_of_default NUMERIC(8,6) NOT NULL, risk_band VARCHAR(20) NOT NULL, model_version VARCHAR(100) NOT NULL, shap_breakdown JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id UUID NOT NULL, before_state JSONB, after_state JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX app_status_idx ON loan_applications(status); CREATE INDEX audit_created_idx ON audit_logs(created_at DESC);
